-- =============================================================
--  CHRONOLEGENDS — 9. « En savoir plus » en hébreu
--  Le site a une version hébraïque : l'interface est traduite, les
--  cartes restent en anglais, et le texte « En savoir plus » des
--  personnages historiques est traduit en hébreu (colonne ci-dessous).
--
--  À exécuter une fois dans Supabase : SQL Editor → New query →
--  coller tout ce fichier → Run. Peut être relancé sans danger.
-- =============================================================

alter table cartes add column if not exists en_savoir_plus_he text;

alter table cartes drop constraint if exists en_savoir_plus_longueur;
alter table cartes add constraint en_savoir_plus_longueur
  check (char_length(en_savoir_plus) <= 1000 and char_length(en_savoir_plus_en) <= 1000
         and char_length(en_savoir_plus_he) <= 1000);

-- ---------- Textes des 46 personnages historiques ----------

-- Alexandre le Grand
update cartes set en_savoir_plus_he = $$תלמידו של אריסטו, הוא ירש את אביו פיליפוס השני, שנרצח בשנת 336 לפנה״ס. לאחר שהביס את דריווש השלישי באיסוס ובגאוגמלה, ייסד ערים רבות, ובהן אלכסנדריה שבמצרים. כשהגיע לנהר היפאסיס בהודו, סירבו חייליו המותשים להמשיך הלאה. הוא מת בבבל בגיל 32. האימפריה שלו התחלקה במהרה בין מצביאיו, אך התרבות היוונית הכתה שורשים עמוקים במזרח ופתחה את התקופה ההלניסטית.$$ where id = 'alexandre';

-- Archimède
update cartes set en_savoir_plus_he = $$ייתכן שלמד באלכסנדריה לפני ששב לסירקוזה, שם עבד בשירות המלך הירון השני. מיוחסים לו בורג ארכימדס להעלאת מים, מערכות גלגלות ותורת המנוף: ״תנו לי נקודת משען ואזיז את העולם.״ הוא חישב ערך מדויק מאוד של פאי ואת השטחים והנפחים של צורות מעוקלות. בזמן המצור הרומי הגנו מכונותיו על העיר. לפי המסורת, כשהיה שקוע בבעיה, נהרג בידי חייל למרות הפקודה לחוס על חייו.$$ where id = 'archimede';

-- Aristote
update cartes set en_savoir_plus_he = $$נולד בסטגירה שבמקדוניה ולמד כעשרים שנה באקדמיה של אפלטון באתונה. בשנת 335 לפנה״ס ייסד שם בית ספר משלו, הליקאון; תלמידיו כונו ״פריפטטיים״ משום שלימד תוך כדי הליכה. הוא צפה במאות מיני בעלי חיים ומיין אותם, וכך הניח יסודות לביולוגיה. לאחר מות אלכסנדר, העוינות כלפי המקדונים הבריחה אותו מאתונה; הוא מת בשנה שלאחר מכן בכלקיס. כתביו עיצבו את המחשבה האירופית והערבית עד תקופת הרנסנס.$$ where id = 'aristote';

-- Ashoka
update cartes set en_savoir_plus_he = $$נכדו של צ׳נדרגופטה, הוא ירש אימפריה שכבר השתרעה על רוב תת־היבשת. לפי צווים שלו עצמו, כיבוש קלינגה סביב 261 לפנה״ס עלה בחייהם של יותר ממאה אלף איש, ולאחר מכן הביע חרטה. מאז קידם את הדהרמה: סובלנות בין הדתות, כבוד לחיים ודאגה לנתיניו. הוא שלח שליחויות בודהיסטיות עד סרי לנקה והעולם ההלניסטי. כותרת האריות של העמוד שלו בסרנאת היא כיום הסמל הלאומי של הודו.$$ where id = 'ashoka';

-- Averroes (Ibn Rushd)
update cartes set en_savoir_plus_he = $$נכדו של שופט מפורסם בקורדובה, הוא למד משפט, רפואה ופילוסופיה. הח׳ליף האלמווחדי אבו יעקוב יוסף ביקש ממנו לבאר את כתבי אריסטו, והוא פירש אותם שורה אחר שורה. בספרו ״הפרכת ההפרכה״ הגן על הפילוסופיה מפני התאולוג אל־ע׳זאלי וטען שאינה סותרת את הדת. כשנפל מחסד סביב 1195, נשרפו חלק מספריו, עד שהוחזר לחצר. הוא מת במרקש; דנטה מזכיר אותו ב״הקומדיה האלוהית״.$$ where id = 'averroes-ibn-rushd';

-- Ban Zhao
update cartes set en_savoir_plus_he = $$בתו של ההיסטוריון באן ביאו ואחותו של המצביא באן צ׳או, היא קיבלה השכלה נדירה לאישה בתקופתה. היא התאלמנה בצעירותה וזומנה לחצר בידי הקיסר הֶה, שם לימדה קיסריות ונשות ארמון. היא כתבה את הטבלאות ואת החיבור על האסטרונומיה ב״ספר האן״. היא כתבה גם את ״לקחים לנשים״, המטיף לענווה ולצייתנות אך מגן על זכותן של נשים להשכלה. היא ייעצה לקיסרית האם דנג בתקופת עוצרותה.$$ where id = 'ban-zhao';

-- Siddhartha Gautama
update cartes set en_savoir_plus_he = $$לפי המסורת, הוא נולד כנסיך בלומביני, בנפאל של ימינו, לשבט השאקיה. בהיותו מזועזע מהזקנה, מהמחלה ומהמוות, עזב את משפחתו בסביבות גיל 29 כדי לחפש קץ לסבל. לאחר שנים של סגפנות, השיג את ההתעוררות תחת עץ בבודה גאיה. מאז לימד את ארבע האמיתות הנאצלות ואת הדרך האמצעית, וייסד קהילה של נזירים ונזירות. הוא מת בקושינגר בגיל 80 בקירוב; תורתו הועברה בעל פה לפני שהועלתה על הכתב.$$ where id = 'bouddha';

-- Boudicca
update cartes set en_savoir_plus_he = $$אשתו של המלך פרסוטגוס, היא ראתה את ממלכת האיקני מסופחת לרומא עם מות בעלה. לפי ההיסטוריון טקיטוס, היא הולקתה ובנותיה עונו בידי חיילים רומאים. אז הקימה את האיקני ושכניהם למרד, והם החריבו את קמולודונום (קולצ׳סטר), לונדיניום (לונדון) וורולמיום. צבאה נמחץ לבסוף בידי המושל סואטוניוס פאולינוס, והיא מתה זמן קצר לאחר מכן, אולי מרעל. פסל המציג אותה על מרכבתה עומד כיום ליד בתי הפרלמנט בלונדון.$$ where id = 'boudicca';

-- Jules César
update cartes set en_savoir_plus_he = $$נולד למשפחה פטריקית ותיקה, והתחבר עם פומפיוס וקרסוס בטריומווירט הראשון. בשנת 49 לפנה״ס חצה את הרוביקון עם לגיונותיו ופתח במלחמת אזרחים נגד פומפיוס. בשלטונו תיקן את לוח השנה: הלוח היוליאני הוא אבי הלוח שלנו. באידוס של מרץ, 44 לפנה״ס, נדקר בידי סנאטורים, ובהם ברוטוס וקסיוס. בנו המאומץ אוקטביאנוס הפך לימים לאוגוסטוס, הקיסר הראשון של רומא.$$ where id = 'cesar';

-- Chandragupta Maurya
update cartes set en_savoir_plus_he = $$מעט ידוע על מוצאו. יחד עם יועצו צ׳נאקיה, שלו מיוחס ה״ארתשסטרה״, חיבור על תורת המדינה, הפיל את שושלת ננדה. הוא ניצל את יציאת צבאות אלכסנדר כדי להשתלט על צפון־מערב הודו, ואחר כך חתם על הסכם עם המצביא היווני סלאוקוס. השגריר היווני מגסתנס תיאר את בירתו, פטליפוטרה. לפי המסורת הג׳ייניסטית, ויתר על כס המלכות כדי להיות נזיר ומת בצום בדרום הודו.$$ where id = 'chandragupta';

-- Cléopâtre VII
update cartes set en_savoir_plus_he = $$צאצאית של תלמי, אחד ממצביאי אלכסנדר, היא הייתה הראשונה בשושלתה שדיברה מצרית, מלבד יוונית ועוד כמה שפות. לאחר שאחיה תלמי השלושה־עשר דחק אותה מהשלטון, השיבה לעצמה את כס המלכות בעזרת קיסר וילדה לו בן, קיסריון. עם מרקוס אנטוניוס נולדו לה שלושה ילדים, והם ארגנו מחדש את המזרח הרומי. לאחר התבוסה הימית באקטיום בשנת 31 לפנה״ס שם אנטוניוס קץ לחייו; קלאופטרה מתה זמן קצר לאחר מכן באלכסנדריה, לפי המסורת מהכשת פתן.$$ where id = 'cleopatre';

-- Confucius
update cartes set en_savoir_plus_he = $$בן למשפחה צנועה מן האצולה הזוטרה, מילא כמה תפקידים במדינת לוּ, ואחר כך נדד מחצר לחצר והציע את רעיונותיו לשליטים, בהצלחה מועטה. הוא לימד חסד (רֶן), כבוד לטקסים, כיבוד הורים וערכה של הלמידה. הוא קיבל תלמידים מכל רקע, דבר חדשני בזמנו. בתקופת שושלת האן הפכה תורתו לבסיס להכשרת פקידים, והבחינות הקיסריות התבססו על הכתבים הקונפוציאניים עד 1905.$$ where id = 'confucius';

-- Cyrus le Grand
update cartes set en_savoir_plus_he = $$בן לשושלת האחמנית הפרסית, הוא הפיל סביב 550 לפנה״ס את אדונו המדי אסטיאגס. אחר כך הביס את קרויסוס, מלך לידיה העשיר, ונכנס לבבל. הוא הניח לעמים הנכבשים לשמור על מנהגיהם ופולחניהם; לפי התנ״ך, התיר לגולי יהודה לשוב לירושלים ולבנות מחדש את המקדש. גליל כורש, השמור במוזיאון הבריטי, מפאר את כיבוש בבל. הוא נפל בקרב במרכז אסיה; קברו עומד עד היום בפסרגדה.$$ where id = 'cyrus-ii';

-- Darius Ier
update cartes set en_savoir_plus_he = $$הוא עלה לשלטון בשנת 522 לפנה״ס לאחר שחיסל טוען לכתר, ואחר כך דיכא שורה של מרידות ברחבי האימפריה. את הסיפור הזה חרט על הצוק בבהיסטון בשלוש שפות; הכתובת אפשרה לפענח את כתב היתדות במאה ה־19. הוא טבע מטבע זהב, הדרכמון, וחפר תעלה שחיברה את הנילוס לים סוף. מסעו נגד אתונה נכשל במרתון בשנת 490 לפנה״ס. הוא קבור בקבר החצוב בצוק בנקש־ה־רוסתם.$$ where id = 'darius-ier';

-- Ézana
update cartes set en_savoir_plus_he = $$הוא עלה לכס המלכות כילד, תחת עוצרותה של אמו. מורו פרומנטיוס, נוצרי מצור, מילא תפקיד מרכזי בהתנצרותו ולימים היה לבישוף הראשון של אכסום. על מטבעותיו הראשונים של עזאנה מופיעים הדיסקוס והסהר של האלים הקדומים, ועל המאוחרים – הצלב. כתובותיו בגעז, בסבאית וביוונית מתארות את מסעותיו, בייחוד נגד מרואה שבסודן של ימינו. הכנסייה האורתודוקסית האתיופית מעריצה אותו כקדוש.$$ where id = 'ezana';

-- Hammurabi
update cartes set en_savoir_plus_he = $$כשהחל את שלטונו, הייתה בבל רק עיר אחת מני רבות. במלחמה ובדיפלומטיה הכניע את שכניו, ובהם לרסה ומארי, ואיחד את מסופוטמיה תחת שלטונו. החוקים שלו קובעים עונשים לפי המעמד החברתי ולעיתים מחילים את עקרון הגמול: ״עין תחת עין״. בראש האסטלה הוא מתואר מקבל את הסמכות משמש, אל הצדק. האסטלה נלקחה כשלל לאיראן סביב 1150 לפנה״ס ונתגלתה מחדש בשושן בשנת 1901.$$ where id = 'hammurabi';

-- Hannibal Barca
update cartes set en_savoir_plus_he = $$בנו של המצביא חמילקר ברקה, ולפי המסופר נשבע בילדותו איבת עולם לרומא. הוא יצא מספרד עם עשרות אלפי חיילים ופילי מלחמה, וחצה את הפירנאים ואחר כך את האלפים בסתיו. לאחר קאנאי נשאר באיטליה חמש־עשרה שנה בלי שהצליח לכבוש את רומא. הוא הוחזר לאפריקה והובס בידי סקיפיו אפריקנוס בזמה בשנת 202 לפנה״ס. בגלות שירת מלכים במזרח, ולבסוף בלע רעל כדי שלא יימסר לרומאים.$$ where id = 'hannibal';

-- Haroun Al Rachid
update cartes set en_savoir_plus_he = $$בנו של הח׳ליף אל־מהדי, הוא עלה לשלטון בשנת 786. וזירים רבי־עוצמה ממשפחת הברמכים ניהלו את האימפריה עד נפילתם הפתאומית בשנת 803. בגדאד, שייסד סבו, הפכה לאחת הערים הגדולות בעולם. הוא החליף משלחות עם קרל הגדול, ולפי הכרוניקות הפרנקיות שלח לו פיל בשם אבול־עבאס. הוא מת במסע מלחמה בטוס שבפרס. היריבות בין בניו אל־אמין ואל־מאמון הובילה לאחר מכן למלחמת אזרחים.$$ where id = 'haroun-al-rachid';

-- Hatchepsout
update cartes set en_savoir_plus_he = $$בתו של פרעה תחותמס הראשון ואשתו של תחותמס השני, היא הייתה לעוצרת של תחותמס השלישי הצעיר, ואחר כך הכתירה את עצמה לפרעה. היא מתוארת עם סמלי המלכות הגבריים, ובהם הזקן המלאכותי. המשלחת לארץ פונט הביאה ממנה קטורת, הובנה ועצי מור. לאחר מותה נמחקו שמה ודמויותיה מאתרים רבים. המומיה שלה זוהתה בשנת 2007 בזכות שן.$$ where id = 'hatchepsout';

-- Hérode le Grand
update cartes set en_savoir_plus_he = $$בנו של פקיד אדומי בשירות החשמונאים, הוא מונה למלך יהודה בידי הסנאט הרומי בשנת 40 לפנה״ס וכבש את ירושלים שלוש שנים לאחר מכן. הוא הרחיב את הר הבית, שקיר התמך המערבי שלו, הכותל, עומד עד היום. הוא בנה גם את המבצרים מצדה והרודיון, שבו נמצא קברו בשנת 2007. מתוך חשדנות הוציא להורג את אשתו מרים ושלושה מבניו. לאחר מותו חולקה ממלכתו בין בניו שנותרו בחיים.$$ where id = 'herode-le-grand';

-- Hérodote
update cartes set en_savoir_plus_he = $$נולד בעיר יוונית באסיה הקטנה שהייתה אז תחת שלטון פרסי, ונדד למצרים, לבבל, לפניקיה ועד חופי הים השחור. הוא תשאל את בני המקום, אסף מסורות ותיאר את מנהגיהם של עמים רבים. מטרתו, כך כתב, הייתה שמעשיהם הגדולים של היוונים והברברים, כלומר מי שאינם יוונים, לא יישכחו. הוא שילב חקירה עם סיפורי פלאים, דבר שהביא עליו גם ביקורת. את שנותיו האחרונות עשה בתורואי, מושבה יוונית בדרום איטליה.$$ where id = 'herodote';

-- Hillel l'ancient
update cartes set en_savoir_plus_he = $$הוא עלה מבבל לירושלים כדי ללמוד, ולפי התלמוד היה עני כל כך שיום אחד טיפס על גג בית המדרש כדי לשמוע את השיעורים. הוא הפך לאחד מגדולי המורים בדורו. כשהתבקש ללמד את כל התורה על רגל אחת, השיב: ״דעלך סני לחברך לא תעביד – מה ששנוא עליך אל תעשה לחברך. זו היא כל התורה כולה, ואידך פירושה הוא.״ מחלוקותיו עם בית שמאי המחמיר ממלאות את התלמוד, ולרוב ההלכה כדעת בית הלל.$$ where id = 'hillel-l-ancient';

-- Hypatie
update cartes set en_savoir_plus_he = $$בתו של המתמטיקאי תאון מאלכסנדריה, היא עבדה איתו על פירושים לתלמי ולאוקלידס. היא ניהלה בית ספר נודע, ולימדה את הפילוסופיה של אפלטון ואסטרונומיה לתלמידים פגאנים ונוצרים כאחד. בהיותה יועצת מוערכת של הנציב אורסטס, נקלעה לסכסוך שלו עם הבישוף קירילוס. במרץ 415 גררו אותה המון נוצרי ממרכבתה ורצחו אותה. במשך הדורות הפכה לסמל של המדע ושל חופש המחשבה.$$ where id = 'hypatie';

-- Ibn Sina (Avicenne)
update cartes set en_savoir_plus_he = $$נולד ליד בוכרה, ידע את הקוראן בעל פה בגיל 10 וכבר בגיל 16 טיפל בחולים. לאחר שריפא את האמיר הסמאני, זכה לגישה לספרייתו העשירה. מאז עשה את חייו בשירות נסיכים שונים, בין תקופות של חסד, בריחה ומאסר, וכתב ללא הרף גם בדרכים. ״ספר הריפוי״ שלו הוא אנציקלופדיה פילוסופית ומדעית עצומה. הוא מת בהמדאן שבאיראן, שם הוקם לכבודו מאוזוליאום.$$ where id = 'ibn-sina';

-- Imhotep
update cartes set en_savoir_plus_he = $$שמו מופיע על בסיס פסל של ג׳וסר, לצד תאריו: קנצלר, כוהן גדול של און (הליופוליס), ראש הפסלים. פירמידת המדרגות היא המונומנט הגדול הראשון שנבנה כולו מאבן מסותתת. כאלפיים שנה לאחר מותו סגדו לו המצרים כאל הרפואה והחוכמה, בנו של האל פתח. היוונים זיהו אותו עם אל הרפואה שלהם, אסקלפיוס. קברו מעולם לא נמצא.$$ where id = 'imhotep';

-- Jeanne d'Arc
update cartes set en_savoir_plus_he = $$נולדה בדומרמי, בגבולות לורן, ולדבריה החלה לשמוע מגיל 13 את קולותיהם של מיכאל הקדוש, קתרינה הקדושה ומרגרטה הקדושה. בשנת 1429 שכנעה את שארל השביעי לעתיד להפקיד בידיה כוחות. היא נפצעה כמה פעמים, ובשנת 1430 נלכדה בקומפיין בידי הבורגונדים, בעלי בריתם של האנגלים, שמסרו אותה לידיהם. היא נשפטה בעוון כפירה ברואן בבית דין כנסייתי ונשרפה על המוקד בגיל 19. משפט שני טיהר את שמה בשנת 1456; היא הוכרזה קדושה בשנת 1920.$$ where id = 'jeanne-d-arc';

-- Judas Maccabée
update cartes set en_savoir_plus_he = $$בנו של הכוהן מתתיהו, שפתח במרד בשנת 167 לפנה״ס, הוא קיבל את הפיקוד על הלוחמים במות אביו. כינויו ״מכבי״, כנראה ״הפטיש״, והוא הביס כמה פעמים צבאות סלאוקיים גדולים יותר. חנוכת המקדש, שהוקדש קודם לכן לפולחן יווני, נחגגת מדי שנה בחנוכה. הוא כרת ברית עם רומא. לאחר מותו המשיכו אחיו במאבק וייסדו את שושלת החשמונאים, ששלטה ביהודה כמאה שנה.$$ where id = 'judas-maccabee';

-- Kanishka
update cartes set en_savoir_plus_he = $$תאריכיו עדיין שנויים במחלוקת; שלטונו החל כנראה סביב 127 לספירה. הוא משל מפורושפורה (פשאוור) וממתורה, בצומת הדרכים שחיברו את הודו, מרכז אסיה וסין. על מטבעותיו מופיעים אלים יוונים, איראנים והודים וגם הבודהה, עדות למגוון שבאימפריה שלו. המסורת הבודהיסטית מייחסת לו כינוס גדול וסטופה ענקית בפשאוור. אמנות גנדהרה מיזגה השפעות יווניות והודיות ויצרה כמה מהדמויות האנושיות הראשונות של הבודהה.$$ where id = 'kanishka';

-- Nabuchodonosor II
update cartes set en_savoir_plus_he = $$בנו של נבופלאסר, הוא הביס את צבא מצרים בכרכמיש בשנת 605 לפנה״ס, עוד לפני שעלה לכס המלכות. שלטונו, שנמשך יותר מארבעים שנה, היה שיאה של האימפריה הבבלית החדשה. הוא בנה מחדש מקדשים ואת הזיגורט הגדול, אתמננקי, שמזוהה לעיתים קרובות עם מגדל בבל. המסורת היוונית מייחסת לו את הגנים התלויים של בבל, שקיומם לא הוכח. חורבן בית המקדש בירושלים וגלות בבל הותירו חותם עמוק בזיכרון היהודי.$$ where id = 'nabuchodonosor';

-- Périclès
update cartes set en_savoir_plus_he = $$בן למשפחה אתונאית מובילה, הוא נבחר מחדש לאסטרטגוס כמעט מדי שנה ושלט בפוליטיקה של עירו. הוא חיזק את הדמוקרטיה, בין השאר בכך שהעניק שכר לאזרחים שישבו בבתי הדין. הוא השתמש באוצר הברית הדלית, ברית של ערים יווניות, כדי לפאר את האקרופוליס, דבר שהכעיס את בעלות הברית. הוא הוביל את אתונה למלחמת הפלופונסוס נגד ספרטה בשנת 431 לפנה״ס. נאום ההספד שלו, כפי שמסר תוקידידס, הוא מחווה מפורסמת לדמוקרטיה האתונאית.$$ where id = 'pericles';

-- Piye
update cartes set en_savoir_plus_he = $$הוא משל מנפטה, למרגלות ההר הקדוש ג׳בל ברכל. כמאמין אדוק של האל אמון, הציג את עצמו כמי שמשיב את המסורות המצריות. סביב 728 לפנה״ס הפליג במורד הנילוס, כבש את ממפיס וקיבל את כניעתם של נסיכי הדלתא. את מסעו תיעד על אסטלה גדולה, השמורה כיום במוזיאון בקהיר. הוא נקבר מתחת לפירמידה באל־כורו; יורשיו הכושיים החיו את המסורת הזאת בסודן.$$ where id = 'piye';

-- Pythéas
update cartes set en_savoir_plus_he = $$סביב 325 לפנה״ס יצא ממסליה, עבר את עמודי הרקולס (מצר גיברלטר) והפליג לאורך חופי האוקיינוס האטלנטי. הוא הקיף את בריטניה ותיאר את הבדיל של קורנוול ואת הענבר של הים הצפוני. תולה, שש ימי הפלגה צפונה, היא אולי איסלנד או נורווגיה. הוא מדד את קו הרוחב של מסליה וקשר בין הגאות והשפל לירח. החיבור שלו, ״על האוקיינוס״, אבד; הוא מוכר רק מכותבים מאוחרים יותר, שחלקם פקפקו בו.$$ where id = 'pytheas';

-- Qin Shi Huang
update cartes set en_savoir_plus_he = $$שמו המקורי יינג ג׳נג, והוא היה למלך צ׳ין בגיל 13. בתוך כעשור כבש את שש הממלכות היריבות ושם קץ לתקופת הממלכות הלוחמות. הוא נטל לעצמו את התואר החדש ״הקיסר הראשון״, חיבר חומות קיימות, אבות החומה הגדולה, ובנה דרכים ותעלות. שלטונו התאפיין גם בדיכוי קשה: המסורת מספרת על ספרים שנשרפו ועל מלומדים שהוצאו להורג. בהיותו אחוז דיבוק לחיי נצח, מת בעודו בדרכים; שושלתו קרסה ארבע שנים לאחר מכן.$$ where id = 'qin-shi-huang';

-- Rabbi Akiva
update cartes set en_savoir_plus_he = $$לפי המסורת, החל את דרכו כרועה צאן שאינו יודע קרוא וכתוב, ורק בגיל 40 החל ללמוד תורה, בעידודה של אשתו רחל. הוא הפך לאחד מגדולי המורים בדורו, ולו אלפי תלמידים. הוא סידר את לימוד התורה שבעל פה והכין את הקרקע לחיבור המשנה. הוא ראה בבר כוכבא את המשיח המיוחל. הוא נעצר משום שהמשיך ללמד תורה למרות האיסור הרומי, ולפי התלמוד מת על קידוש השם בעודו קורא ״שמע ישראל״.$$ where id = 'rabbi-akiva';

-- Ramsès II
update cartes set en_savoir_plus_he = $$בנו של סתי הראשון, הוא עלה לכס המלכות בגיל 25 בקירוב. כבנאי גדול הקים את מקדשי אבו סימבל, הרחיב את כרנך ולוקסור, וייסד בירה חדשה בדלתא, פר־רעמסס. הקרב בקדש, סביב 1274 לפנה״ס, הסתיים ללא מנצח ברור, אך קירות מקדשיו מציגים אותו כניצחון. נולדו לו כמאה ילדים, ורבים מהם מתו לפניו. המומיה שלו, שנמצאה בשנת 1881, מוצגת כיום בקהיר.$$ where id = 'ramses-ii';

-- Roi David
update cartes set en_savoir_plus_he = $$לפי התנ״ך, הוא בנו הצעיר של ישי מבית לחם; עוד בהיותו נער רועה נמשח בידי שמואל הנביא. כמוזיקאי ניגן בכינור כדי להרגיע את שאול המלך, שלימים רדף אותו. כמלך כבש את ירושלים, העלה אליה את ארון הברית והכין את בניית בית המקדש, שהשלים בנו שלמה. הסיפור המקראי מתעד גם את חטאיו, כמו פרשת בת שבע. כתובת ארמית מהמאה ה־9 לפנה״ס, כתובת תל דן, מזכירה את ״בית דוד״.$$ where id = 'roi-david';

-- Saladin
update cartes set en_savoir_plus_he = $$ממוצא כורדי ויליד תכרית, הוא הלך בעקבות דודו שירכוה למצרים, ושם התמנה לווזיר בשנת 1169. הוא שם קץ לח׳ליפות הפאטמית, ואחר כך הרחיב את שלטונו על סוריה ועל חלק ממסופוטמיה וייסד את השושלת האיובית. בירושלים חס על רוב האוכלוסייה הנוצרית תמורת כופר. מול ריצ׳רד לב הארי חתם על הסכם יפו בשנת 1192, שהותיר את החוף בידי הצלבנים והבטיח לעולי הרגל גישה לירושלים. הוא מת בדמשק, שם עומד קברו.$$ where id = 'saladin';

-- Sappho
update cartes set en_savoir_plus_he = $$היא חיה במיטילני שבאי לסבוס, במשפחה אמידה; ייתכן שהוגלתה לזמן מה לסיציליה. שיריה, שהושרו בליווי נבל, מדברים על אהבה, תשוקה, ידידות ונישואים. מלומדים בעת העתיקה כינסו את יצירתה לתשעה ספרים, ולפי המסופר כינה אותה אפלטון ״המוזה העשירית״. רק שיר שלם אחד שרד; קטעים נוספים נמצאו על פפירוסים מצריים, האחרון שבהם ב־2014. המילים ״ספפי״ ו״לסבית״ נגזרו משמה ומשם האי שלה.$$ where id = 'sappho';

-- Siyaj K'ak'
update cartes set en_savoir_plus_he = $$שמו פירושו ״נולד מן האש״. הוא הגיע לטיקאל ביום שבו מת המלך צ׳אק טוק איצ׳אאק, כנראה באלימות. כעבור שנה עלה לכס המלכות, תחת חסותו, מלך חדש, יאש נון אחין, בנה של דמות הקשורה לטאוטיוואקאן. כתובות מזכירות אותו גם בערי מאיה אחרות, כמו ואשקטון. בואו פתח תקופה של השפעה טאוטיוואקאנית, הניכרת באמנות ובאדריכלות של האזור.$$ where id = 'siyaj-kak';

-- Spartacus
update cartes set en_savoir_plus_he = $$חייל לשעבר, אולי בכוחות העזר של הצבא הרומי, הוא שועבד ואומן בבית ספר לגלדיאטורים בקפואה. בשנת 73 לפנה״ס ברח עם כמה עשרות חברים ומצא מקלט על הר הווזוב. אלפי עבדים הצטרפו אליהם; הם הביסו כמה צבאות רומיים ונדדו ברחבי איטליה. ספרטקוס נפל בקרב נגד קרסוס, וששת אלפים שבויים נצלבו לאורך הדרך האפית. המרד שלו היווה השראה לרומנים, לסרטים ולתנועות פוליטיות רבים.$$ where id = 'spartacus';

-- Sun Tzu
update cartes set en_savoir_plus_he = $$לפי ההיסטוריון סה־מה צ׳יין, שירת את מלך וּ, והוכיח את כישרונו כשאימן את פילגשי הארמון כחיילים. ל״אמנות המלחמה״ שלושה־עשר פרקים קצרים. הרעיון המרכזי בו הוא שהניצחון הטוב ביותר מושג בלי להילחם, בזכות תחבולה, מודיעין והיכרות עם האויב. ״הכר את אויבך והכר את עצמך,״ כתב. הספר תורגם לראשונה לשפה אירופית, צרפתית, בשנת 1772, ועד היום קוראים אותו חיילים, מנהלים וספורטאים.$$ where id = 'sun-tzu';

-- Thalès de Milet
update cartes set en_savoir_plus_he = $$סוחר ונוסע, ולפי המסופר ביקר במצרים, שם מדד את גובהה של פירמידה בעזרת צילה. משפט על מעגלים נושא את שמו. הוא חיפש הסברים טבעיים לעולם בלי לפנות לאלים, וגרס שהכול בא מן המים. לפי הרודוטוס, חזה את ליקוי החמה של 585 לפנה״ס, שעצר קרב בין המדים ללידים. הוא נמנה עם שבעת החכמים של יוון.$$ where id = 'thales';

-- Vercingétorix
update cartes set en_savoir_plus_he = $$בנו של קלטילוס, אציל ארוורני שהוצא להורג משום ששאף למלוכה, הוא הנהיג את מרד הגאלים בשנת 52 לפנה״ס. הוא נקט טקטיקה של אדמה חרוכה כדי להרעיב את הלגיונות והדף את קיסר בגרגוביה. כשהיה נצור באלסיה, המתין לצבא גאלי שיחלץ אותו, אך זה הובס. אז נכנע לקיסר. הוא הוחזק בשבי שש שנים, הוצג בתהלוכת הניצחון של קיסר ברומא ואחר כך הוצא להורג. במאה ה־19 הפך לדמות לאומית בצרפת.$$ where id = 'vercingetorix';

-- K'inich Yax K'uk' Mo'
update cartes set en_savoir_plus_he = $$שמו פירושו בערך ״שמש גדולה, קְוֶצָל, תוכי ארה״. ניתוח עצמותיו מרמז שגדל הרחק מקופאן, אולי באזור טיקאל. מונומנטים מציגים אותו עם טבעות סביב העיניים, עיטור הקשור לטאוטיוואקאן. חמישה־עשר מלכים ירשו אותו; האחרון שבהם, יאש פסאח, תיאר אותו על מזבח Q, המציג את כל שושלת השליטים. קברו נתגלה בשנות ה־90 מתחת לאקרופוליס של קופאן.$$ where id = 'yax-kuk-mo';

-- Zénobie
update cartes set en_savoir_plus_he = $$אשתו של אודנתוס, נסיך מתדמור בעל ברית של רומא, היא נטלה את השלטון לאחר הירצחו בשנת 267, בשם בנם הצעיר ובלאתוס. כשליטה משכילה אירחה בחצרה את הפילוסוף לונגינוס. היא ניצלה את המשבר באימפריה הרומית, וצבאותיה כבשו את מצרים ואת רוב המזרח הקרוב. לאחר שהובסה בידי אורליאנוס, ניסתה לברוח לפרס אך נלכדה ליד הפרת. לפי כמה מקורות, סיימה את ימיה באיטליה, ליד טיבור (טיבולי).$$ where id = 'zenobie';

-- Zhang Qian
update cartes set en_savoir_plus_he = $$סביב 138 לפנה״ס שלח אותו הקיסר וּ לחפש ברית עם היואה־ג׳י נגד השׁיוֹנגנו הנוודים. הוא נלכד בידי השׁיוֹנגנו והוחזק אצלם כעשר שנים, נשא אישה ונולד לו בן, עד שהצליח לברוח. הוא הגיע לבקטריה אך לא הצליח להשיג את הברית. בשובו סיפר בחצר על ממלכות לא מוכרות, על סוסים יקרי ערך ועל סחורות מהודו. הדיווחים שלו עודדו את בית האן להרחיב את השפעתו מערבה ולפתח את המסחר.$$ where id = 'zhang-qian';

-- ---------- Vérification : doit afficher 46 / 46 ----------
select count(*) filter (where en_savoir_plus_he is not null) as en_hebreu,
       count(*) filter (where en_savoir_plus is not null) as avec_en_savoir_plus
from cartes where gamme = 'personnage';
